void decode_from_filename(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (!dst && !dst_size) {
        return;
    }

    size_t i = 0;
    size_t j = 0;
    size_t bit_offset = 0;
    size_t decoded_size = 0;

    while (i < src_size) {
        if (bit_offset == 0) {
            if (dst && j < *dst_size) {
                dst[j] = 0;
            }
            decoded_size++;
            j++;
        }

        unsigned char c = src[i];
        unsigned char decoded_byte = 0;

        if (c >= '0' && c <= '9') {
            decoded_byte = c - '0';
        } else if (c >= 'A' && c <= 'Z') {
            decoded_byte = c - 'A' + 10;
        } else if (c >= 'a' && c <= 'z') {
            decoded_byte = c - 'a' + 36;
        } else if (c == '+') {
            decoded_byte = 62;
        } else if (c == '/') {
            decoded_byte = 63;
        } else {
            i++;
            continue;
        }

        decoded_byte <<= (6 - bit_offset);
        if (dst && j < *dst_size) {
            dst[j - 1] |= decoded_byte;
        }
        bit_offset += 2;

        if (bit_offset == 8) {
            bit_offset = 0;
        }

        i++;
    }

    if (dst_size) {
        *dst_size = decoded_size;
    }
}

void decode_filename_format(unsigned char *dst, size_t *dst_size, const unsigned char *src, size_t src_size) {
    if (dst == NULL) {
        /* Calculate the maximum possible size of the decoded data */
        *dst_size = (src_size * 8) / 8;
        return;
    }

    size_t i;
    size_t pos = 0;
    unsigned char byte = 0;
    size_t bit_count = 0;

    for (i = 0; i < src_size; i++) {
        byte = src[i];
        size_t j;

        for (j = 0; j < 8; j++) {
            if ((byte >> j) & 1) {
                dst[pos++] = 1 << (7 - bit_count % 8);
            }
            bit_count++;
        }
    }

    *dst_size = pos;
}
